declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/_layout.php';$u=require_admin();$msg=(string)($_SESSION['admin_ticket_flash']??'');$err='';unset($_SESSION['admin_ticket_flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$tid=(int)($_POST['ticket_id']??0);$act=(string)($_POST['action']??'');$check=db()->prepare('SELECT id FROM support_tickets WHERE id=?');$check->execute([$tid]);if($tid<=0||!$check->fetchColumn())throw new RuntimeException('Ticket not found.');if($act==='reply'||$act==='note'){$body=trim((string)($_POST['message']??''));if($body==='')throw new RuntimeException('Message cannot be empty.');if(mb_strlen($body)>20000)throw new RuntimeException('Message is too long.');$internal=$act==='note'?1:0;db()->prepare('INSERT INTO support_messages(ticket_id,user_id,is_staff,is_internal,message) VALUES(?,?,1,?,?)')->execute([$tid,$u['id'],$internal,$body]);if($internal)db()->prepare('UPDATE support_tickets SET assigned_admin_id=COALESCE(assigned_admin_id,?),updated_at=NOW() WHERE id=?')->execute([$u['id'],$tid]);else{db()->prepare("UPDATE support_tickets SET status='awaiting_customer',assigned_admin_id=COALESCE(assigned_admin_id,?),updated_at=NOW() WHERE id=?")->execute([$u['id'],$tid]);zoho_crm_try_sync_ticket($tid);ticket_notify_customer($tid);}$_SESSION['admin_ticket_flash']=$internal?'Internal note added.':'Reply sent to the customer.';header('Location: /admin/support.php?id='.$tid.'#conversation');exit;}if($act==='update'){$status=in_array($_POST['status']??'',['open','awaiting_customer','awaiting_staff','answered','closed'],true)?(string)$_POST['status']:'open';$priority=in_array($_POST['priority']??'',['low','normal','high','urgent'],true)?(string)$_POST['priority']:'normal';$assigned=(int)($_POST['assigned_admin_id']??0)?:null;db()->prepare('UPDATE support_tickets SET status=?,priority=?,assigned_admin_id=? WHERE id=?')->execute([$status,$priority,$assigned,$tid]);zoho_crm_try_sync_ticket($tid);$_SESSION['admin_ticket_flash']='Ticket settings updated.';header('Location: /admin/support.php?id='.$tid);exit;}throw new RuntimeException('Unknown ticket action.');}catch(Throwable $e){$err=$e->getMessage();}}
$id=(int)($_GET['id']??0);$ticket=null;$messages=[];if($id){$q=db()->prepare('SELECT t.*,u.name customer_name,u.email,a.name assigned_name,s.name service_name FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users a ON a.id=t.assigned_admin_id LEFT JOIN services s ON s.id=t.service_id WHERE t.id=?');$q->execute([$id]);$ticket=$q->fetch()?:null;if($ticket){$q=db()->prepare('SELECT m.*,u.name FROM support_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? ORDER BY m.id DESC');$q->execute([$id]);$messages=$q->fetchAll();}}
$statuses=['open','awaiting_staff','awaiting_customer','answered','closed'];$status=(string)($_GET['status']??'');if($status!==''&&!in_array($status,$statuses,true))$status='';$sql='SELECT t.*,u.name customer_name,u.email,(SELECT COUNT(*) FROM support_messages m WHERE m.ticket_id=t.id) message_count FROM support_tickets t JOIN users u ON u.id=t.user_id';$args=[];if($status!==''){$sql.=' WHERE t.status=?';$args[]=$status;}$sql.=' ORDER BY FIELD(t.status,"awaiting_staff","open","awaiting_customer","answered","closed"),FIELD(t.priority,"urgent","high","normal","low"),t.updated_at DESC';$q=db()->prepare($sql);$q->execute($args);$tickets=$q->fetchAll();$admins=db()->query("SELECT id,name FROM users WHERE role='admin' AND account_status='active' ORDER BY name")->fetchAll();admin_head($u,'Support Center','support');?>
<link rel="stylesheet" href="/assets/admin-support.css?v=<?=rawurlencode((string)@filemtime(__DIR__.'/../assets/admin-support.css'))?>"><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?>
<div class="support-admin-grid"><section class="card ticket-index"><div class="cardhead"><div><b>TICKETS</b><small class="muted"><?=count($tickets)?> result<?=count($tickets)===1?'':'s'?></small></div></div><div class="ticket-filters"><a class="btn <?=$status===''?'active':''?>" href="/admin/support.php">All</a><?php foreach($statuses as $s):?><a class="btn <?=$status===$s?'active':''?>" href="?status=<?=e($s)?>"><?=e(ucwords(str_replace('_',' ',$s)))?></a><?php endforeach?></div><div class="ticket-list"><?php if(!$tickets):?><div class="ticket-empty">No tickets match this filter.</div><?php endif?><?php foreach($tickets as $t):?><a class="ticket-row <?=$id===(int)$t['id']?'selected':''?>" href="/admin/support.php?id=<?=(int)$t['id']?><?= $status!==''?'&status='.rawurlencode($status):''?>"><div><b>#<?=(int)$t['id']?> <?=e($t['subject'])?></b><small><?=e($t['customer_name'])?> · <?=e(ucfirst($t['category']))?> · <?=e(ucfirst($t['priority']))?> · <?=(int)$t['message_count']?> message<?=((int)$t['message_count']===1?'':'s')?></small><time><?=e(date('d M Y H:i',strtotime((string)$t['updated_at'])))?></time></div><?=admin_badge($t['status'])?></a><?php endforeach?></div></section>
<?php if(!$ticket):?><section class="card ticket-placeholder"><div><span>↗</span><h2>Select a ticket</h2><p>Choose a ticket from the list to reply and manage its status.</p></div></section><?php endif?>
<?php if($ticket):?><section class="card ticket-thread"><div class="ticket-hero"><div><span class="ticket-number">TICKET #<?=(int)$ticket['id']?></span><h2><?=e($ticket['subject'])?></h2><div class="ticket-customer"><a href="/admin/customer.php?id=<?=(int)$ticket['user_id']?>"><?=e($ticket['customer_name'])?></a><span><?=e($ticket['email'])?></span><?php if(!empty($ticket['service_name'])):?><span><?=e($ticket['service_name'])?></span><?php endif?></div></div><?=admin_badge($ticket['status'])?></div>
<form method="post" class="ticket-form ticket-reply-top" id="reply"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="ticket_id" value="<?=(int)$ticket['id']?>"><div class="composer-head"><div><b>Write a response</b><small>Customer replies are emailed automatically.</small></div><a href="/admin/customer.php?id=<?=(int)$ticket['user_id']?>">Customer profile</a></div><textarea id="ticket-reply-message" name="message" rows="5" maxlength="20000" required placeholder="Type your reply or internal note..."></textarea><div class="ai-suggestion-status" id="ai-suggestion-status" aria-live="polite"></div><div class="buttons"><?php if(openai_support_enabled()):?><button class="btn ai-suggest-btn" type="button" id="ai-suggest-reply">Suggest reply with AI</button><?php endif?><button class="btn primary" name="action" value="reply">Send reply</button><button class="btn note-btn" name="action" value="note">Save internal note</button></div></form>
<details class="ticket-settings"><summary>Ticket settings <span><?=e(ucwords(str_replace('_',' ',$ticket['status'])))?> · <?=e(ucfirst($ticket['priority']))?> · <?=e($ticket['assigned_name']?:'Unassigned')?></span></summary><form method="post" class="admin-form-grid ticket-controls"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="ticket_id" value="<?=(int)$ticket['id']?>"><label>Status<select name="status"><?php foreach(['open','awaiting_customer','awaiting_staff','answered','closed'] as $s):?><option value="<?=e($s)?>" <?=$ticket['status']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $p):?><option value="<?=e($p)?>" <?=$ticket['priority']===$p?'selected':''?>><?=e(ucfirst($p))?></option><?php endforeach?></select></label><label>Assigned to<select name="assigned_admin_id"><option value="">Unassigned</option><?php foreach($admins as $a):?><option value="<?=(int)$a['id']?>" <?=$ticket['assigned_admin_id']==$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach?></select></label><button class="btn">Save settings</button></form></details>
<div class="conversation-head" id="conversation"><div><b>Conversation</b><small><?=count($messages)?> message<?=count($messages)===1?'':'s'?> · newest first</small></div><a href="#reply">Reply at top ↑</a></div><div class="messages"><?php foreach($messages as $m):?><article class="message <?=$m['is_internal']?'internal':($m['is_staff']?'staff':'customer')?>"><div class="message-meta"><div><b><?=e($m['name']?:'Unknown')?></b><span><?=$m['is_internal']?'Internal note':($m['is_staff']?'Staff reply':'Customer')?></span></div><time><?=e(date('d M Y H:i',strtotime((string)$m['created_at'])))?></time></div><div class="message-body"><?=nl2br(e($m['message']))?></div></article><?php endforeach?></div></section><?php endif?></div><?php if($ticket&&openai_support_enabled()):?><script>(()=>{const button=document.getElementById('ai-suggest-reply'),field=document.getElementById('ticket-reply-message'),status=document.getElementById('ai-suggestion-status');button?.addEventListener('click',async()=>{button.disabled=true;status.textContent='Generating a suggestion…';try{const response=await fetch('/api/admin-ticket-suggestion.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?=json_encode(csrf())?>},body:JSON.stringify({ticket_id:<?=(int)$ticket['id']?>})}),result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Suggestion failed.');field.value=result.suggestion||'';field.focus();status.textContent='Suggestion ready — review and edit it before sending.';}catch(error){status.textContent=error.message||String(error);}finally{button.disabled=false;}});})();</script><?php endif?><?php admin_foot(); ?>
